Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include<iostream>
#include<vector>
#include <algorithm>
using namespace std;
const int p1=998244353,p2=1e9+7,B=1e6;
vector<int> v[7];
int sum[7];
long long n,ord,ans;
void dfs1(int x,int len){
	++ord,v[len].push_back((ord-x+p1)%p1);
	(sum[len]+=v[len].back())%=p2;
	if(len==6) return;
	for(int i=0;i<=9;++i) dfs1(x*10+i,len+1);
}
void dfs2(long long x){
	if(x>n) return;
	if(x*B+B-1<=n&&x*B*10>n){
		long long now=ord;
		for(int i=0,m=1;i<=6;++i,m*=10){
			int sz=v[i].size(),dt=((now-x*m)%p1+p1)%p1;
			int pos=lower_bound(v[i].begin(),v[i].end(),p1-dt)-v[i].begin();
			ans=(ans+1ll*dt*sz+sum[i])%p2;
			ans=(ans-1ll*(sz-pos)*p1%p2+p2)%p2;
			ord+=sz;
		}
		return;
	}
	++ord;
	ans=(ans+((ord-x)%p1+p1)%p1)%p2;
	for(int i=0;i<=9;++i) dfs2(x*10+i);
}
int main(){
	cin>>n;
	dfs1(0,0),ord=0;
	for(int i=0;i<=6;++i) sort(v[i].begin(),v[i].end());
	for(int i=1;i<=9;++i) dfs2(i);
	cout<<ans;
	return 0;
}

</original_code>

